// One sheet row = one invoice with one line. Edit SELLER once: these are
// your own company details, written into every invoice.
const SELLER = {
  name: 'Seller GmbH',
  address: { city: 'Berlin', post_code: '10115', country_code: 'DE' },
  vat_id: 'DE123456789',
  contact_name: 'Accounts',
  contact_phone: '+49 30 1234567',
  contact_email: 'accounts@example.com',
  electronic_address: 'seller@example.com',
};
const PAYMENT_IBAN = 'DE75512108001245126199';

// Sheets in a German locale write 1.234,50. Accept both 1234.50 and 1.234,50.
function num(value, column) {
  let text = String(value ?? '').trim().replace(/\s/g, '');
  if (text.includes(',')) text = text.replace(/\./g, '').replace(',', '.');
  const n = Number(text);
  if (text === '' || !Number.isFinite(n)) {
    throw new Error(`Column "${column}" is not a number: "${value}"`);
  }
  return n;
}
const cents = (n) => Math.round(n * 100);
const money = (c) => (c / 100).toFixed(2);

const row = $json;
const quantity = num(row.quantity, 'quantity');
const unitPrice = num(row.unit_price, 'unit_price');
const rate = num(row.vat_rate, 'vat_rate');

// The amounts are computed HERE, by this template; invowerk writes them into
// the XML as given and checks the result against the rules, it does not
// recompute them. Check the figures before you send the first invoice.
const net = cents(quantity * unitPrice);
const tax = Math.round((net * rate) / 100);

return {
  json: {
    invoice_number: String(row.invoice_number),
    issue_date: String(row.issue_date),
    due_date: row.due_date ? String(row.due_date) : '',
    buyer_reference: String(row.buyer_reference ?? ''),
    buyer_email: String(row.buyer_email),
    payment_iban: PAYMENT_IBAN,
    seller: SELLER,
    buyer: {
      name: String(row.buyer_name),
      address: {
        city: String(row.buyer_city),
        post_code: String(row.buyer_post_code),
        country_code: String(row.buyer_country || 'DE').toUpperCase(),
      },
      electronic_address: String(row.buyer_email),
    },
    lines: [
      {
        name: String(row.item),
        net_price: unitPrice.toFixed(2),
        quantity: String(quantity),
        line_net_amount: money(net),
        tax_category: 'S',
        tax_rate: rate.toFixed(2),
      },
    ],
    tax_breakdown: [
      { taxable_amount: money(net), tax_amount: money(tax), category: 'S', rate: rate.toFixed(2) },
    ],
    totals: { line_total: money(net), tax_exclusive: money(net), tax_inclusive: money(net + tax) },
  },
};

// The node returns the XRechnung as text in `data`; turn it into an XML file.
const invoice = $('Build invoice body').item.json;
return {
  json: { invoice_number: invoice.invoice_number, buyer_email: invoice.buyer_email },
  binary: {
    invoice: {
      data: Buffer.from($json.data, 'utf8').toString('base64'),
      mimeType: 'application/xml',
      fileName: `${invoice.invoice_number}.xml`,
      fileExtension: 'xml',
    },
  },
};
